def plan(n_exams):
    """Chia câu lí thuyết giải tích cho các đề: {thứ tự đề: [(vị trí, câu), ...]}.
    Đề nào cũng có 1 câu, các đề ở vị trí lẻ có 2 câu; đi vòng qua các chủ đề để hai đề liền nhau không trùng chủ đề."""
    slots = sorted(THEORY)
    tokens, i = [], 0
    while len(tokens) < sum(len(v) for v in THEORY.values()):
        for s in slots:
            if i < len(THEORY[s]):
                tokens.append((s, THEORY[s][i]))
        i += 1
    out = {k: [tokens[k]] for k in range(min(n_exams, len(tokens)))}
    rest = tokens[n_exams:]
    for k in range(1, n_exams, 2):
        for t in rest:
            if all(t[0] != u[0] for u in out.get(k, [])):
                out.setdefault(k, []).append(t)
                rest.remove(t)
                break
    return out
